        require(account != address(0), "PaymentSplitter: account is the zero address");
        require(shares_ > 0, "PaymentSplitter: shares are 0");
        require(_shares[account] == 0, "PaymentSplitter: account already has shares");

        _payees.push(account);
        _shares[account] = shares_;
        _totalShares = _totalShares + shares_;
        emit PayeeAdded(account, shares_);
    }
}

// SPDX-License-Identifier: BSD-3
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/interfaces/IERC2981.sol";

contract Royalties is IERC2981{
  struct Fraction{
    uint16 numerator;
    uint16 denominator;
  }

  struct Royalty{
    address receiver;
    Fraction fraction;
  }

  Royalty public defaultRoyalty;
  //mapping(uint => Royalty) public tokenRoyalties;

  constructor(address receiver, uint16 royaltyNum, uint16 royaltyDenom) {
    _setDefaultRoyalty(receiver, royaltyNum, royaltyDenom);
  }

  // view
  function royaltyInfo(uint256, uint256 _salePrice) public view virtual returns(address, uint256) {
    /*
    Royalty memory royalty = _tokenRoyaltyInfo[_tokenId];
    if (royalty.receiver == address(0)) {
        royalty = _defaultRoyaltyInfo;
    }
    */

    uint256 royaltyAmount = (_salePrice * defaultRoyalty.fraction.numerator) / defaultRoyalty.fraction.denominator;
    return (defaultRoyalty.receiver, royaltyAmount);
  }

  function supportsInterface(bytes4 interfaceId) public view virtual returns(bool) {
    return interfaceId == type(IERC2981).interfaceId;
  }

  function _setDefaultRoyalty(address receiver, uint16 royaltyNum, uint16 royaltyDenom) internal {
    defaultRoyalty.receiver = receiver;
    defaultRoyalty.fraction = Fraction(royaltyNum, royaltyDenom);
  }
}

// SPDX-License-Identifier: BSD-3
pragma solidity ^0.8.9;

import {IERC165} from "@openzeppelin/contracts/interfaces/IERC165.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IERC721Metadata} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";

//import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";

import {IERC721Batch} from "../Common/ERC721/IERC721Batch.sol";

abstract contract FuturistsData{
  enum SaleState {
    NONE,
    ALLOWLIST,
    PUBLIC
  }

  struct MintConfig{
    uint64 ethPrice;
    uint8 maxOrder;
    uint8 maxWallet;
    uint16 maxSupply;
    uint8 saleState;
  }

  struct Owner{
    uint16 balance;
    uint16 purchased;
    uint16 redeemed;
    uint16 vouchers;
  }

  struct TokenRange{
    uint16 lower;
    uint16 upper;
    uint16 supply;
  }

  struct Token{
    address owner;
    uint16 id;
  }

  uint256 public constant MAX_SUPPLY = 10000;

  address public crossmintOperator = 0xdAb1a1854214684acE522439684a145E62505233;
  bool public isOsEnabled = true;
  uint16 public reserved = 200;
  string public tokenURIPrefix;
  string public tokenURISuffix;

  mapping(uint256 => Token) public tokens;
  mapping(address => Owner) public owners;

  MintConfig public CONFIG = MintConfig(
       1 ether,  //ethPrice
       1,        //maxOrder
       1,        //maxWallet
    1111,        //maxSupply
       0         //saleState
  );

  TokenRange public range = TokenRange(
    1, //lower
    0, //upper
    0  //supply
  );
}

abstract contract Futurists721 is FuturistsData, Context, ERC165, IERC721, IERC721Metadata {
  error CantApproveOwner();
  error NotERC721Receiver();
  error NotOwnerOrApproved();
  error TokenNonexistant();
  error TokenNotOwned();
  error TokenExists();
  error ZeroAddress();

  string public name;
  string public symbol;

  mapping(uint256 => address) internal _tokenApprovals;
  mapping(address => mapping(address => bool)) private _operatorApprovals;

  constructor(){
    name = "Future Factory Futurists";
    symbol = "FUTUR";
  }

  //public view
  function balanceOf(address owner) public view returns(uint256){
    if(owner == address(0)) revert ZeroAddress();
    return owners[owner].balance;
  }

  function burned() public view returns(uint256){
    return owners[address(0)].balance;
  }

  function ownerOf(uint256 tokenId) public view virtual returns(address){
    if(!_exists(tokenId)) revert TokenNonexistant();
    return tokens[tokenId].owner;
  }

  // function supportsInterface(bytes4 interfaceId) public view virtual override(ERC165, IERC165) returns(bool){
  //   return
  //     interfaceId == type(IERC721).interfaceId ||
  //     interfaceId == type(IERC721Metadata).interfaceId ||
  //     super.supportsInterface(interfaceId);
  // }

  function totalSupply() public view virtual returns( uint256 ){
    return range.supply - burned();
  }


  //approvals
  function approve(address operator, uint256 tokenId) public virtual{
    address owner = tokens[tokenId].owner;
    if(operator == owner) revert CantApproveOwner();

    if(_msgSender() == owner)
      _approve(operator, tokenId);
    else if(isApprovedForAll(owner, _msgSender()))
      _approve(operator, tokenId);
    else 
      revert NotOwnerOrApproved();
  }

  function getApproved(uint256 tokenId) public view returns(address){
    if(!_exists(tokenId)) revert TokenNonexistant();
    return _tokenApprovals[tokenId];
  }

  function isApprovedForAll(address owner, address operator) public view returns(bool){
    return _operatorApprovals[owner][operator];
  }

  function setApprovalForAll(address operator, bool approved) public virtual{
    _operatorApprovals[_msgSender()][operator] = approved;
    emit ApprovalForAll(_msgSender(), operator, approved);
  }


  //transfers
  function safeTransferFrom(address from, address to, uint256 tokenId) public virtual{
    safeTransferFrom(from, to, tokenId, "");
  }

  function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory _data) public virtual{
    if(!_isApprovedOrOwner(_msgSender(), tokenId)) revert NotOwnerOrApproved();

    _safeTransfer(from, to, tokenId, _data);
  }

  function transferFrom(address from, address to, uint256 tokenId) public virtual{
    if(!_isApprovedOrOwner(_msgSender(), tokenId)) revert NotOwnerOrApproved();

    _transfer(from, to, tokenId);
  }


  //internal
  function _approve(address to, uint256 tokenId) internal{
    _tokenApprovals[tokenId] = to;
    emit Approval(tokens[tokenId].owner, to, tokenId);
  }

  // solhint-disable-next-line no-empty-blocks
  function _beforeTokenTransfer(address from, address to, uint256 tokenId) internal virtual {}

  function _burn(address from, uint256 tokenId) internal{
    if(ownerOf(tokenId) != from) revert TokenNotOwned();

    // Clear approvals
    delete _tokenApprovals[tokenId];
    _beforeTokenTransfer(from, address(0), tokenId);

    _transfer(from, address(0), tokenId);
  }

  function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory _data) private returns(bool) {
    if (Address.isContract(to)) {
      try IERC721Receiver(to).onERC721Received(_msgSender(), from, tokenId, _data) returns (bytes4 retval) {
        return retval == IERC721Receiver.onERC721Received.selector;
      } catch (bytes memory reason) {
        if (reason.length == 0) {
          revert NotERC721Receiver();
        } else {
